/**
 * iOS treats Web Audio as ambient sound and mutes it with the ringer switch.
 * Media playback is exempt. Declaring a playback session (iOS 17+) or, only on
 * older iOS, looping a silent media element from inside the first tap moves
 * the page into the playback category so the game is heard with the switch on.
 */
const SILENT_WAV =
  'data:audio/wav;base64,';

interface AudioSessionLike {
  type: string;
}

export type SessionMode = 'none' | 'api' | 'element';

let mode: SessionMode = 'none';
let silence: HTMLAudioElement | null = null;

/**
 * Call from inside a user gesture, alongside creating the AudioContext.
 *
 * The media element is a last resort for iOS 16 and older. On iOS 17+ the
 * Audio Session API does the job alone, and the element must not exist: Brave
 * on iOS watches for media elements and offers to add them to its Playlist on
 * a long press, which is the one gesture this game is made of.
 */
export function claimPlaybackSession(): void {
  const session = (navigator as Navigator & { audioSession?: AudioSessionLike }).audioSession;
  if (session) {
    try {
      session.type = 'playback';
      mode = 'api';
      return;
    } catch {
      // Not settable; fall through to the media element
    }
  }
  if (!silence) {
    silence = document.createElement('audio');
    silence.loop = true;
    silence.setAttribute('playsinline', '');
    silence.preload = 'auto';
    silence.src = SILENT_WAV;
    silence.setAttribute('aria-hidden', 'true');
    silence.style.display = 'none';
    document.body.append(silence);
    mode = 'element';
  }
  void silence.play().catch(() => undefined);
}

/** How the playback session was claimed, for the debug readout. */
export function playbackSessionMode(): SessionMode {
  return mode;
}

export function pausePlaybackSession(): void {
  silence?.pause();
}

export function resumePlaybackSession(): void {
  if (silence) void silence.play().catch(() => undefined);
}
